import inspect
import json

import pytest

from streamfeed.importer import import_events
from streamfeed.reader import decode_chunks


@pytest.mark.parametrize(
    "events",
    [
        [{"name": "小雅", "note": "ready 🚀"}, {"name": "Zoë"}],
        [{"name": "Renée", "note": "café"}],
        [{"name": "𐍈", "note": "four-byte code point 🌍"}],
    ],
)
def test_every_byte_boundary_preserves_multilingual_events(events):
    text = "".join(json.dumps(event, ensure_ascii=False) + "\n" for event in events)
    payload = text.encode("utf-8")
    for split in range(1, len(payload)):
        assert import_events([payload[:split], payload[split:]]) == events


def test_many_boundaries_can_each_land_inside_different_code_points():
    events = [{"name": "你好🌍é𐍈", "note": "one byte per chunk"}]
    payload = (json.dumps(events[0], ensure_ascii=False) + "\n").encode("utf-8")
    assert import_events([bytes([byte]) for byte in payload]) == events


@pytest.mark.parametrize("character", ["é", "小", "🚀", "𐍈"])
def test_every_incomplete_multibyte_prefix_fails_explicitly(character):
    encoded = character.encode("utf-8")
    prefix = b'{"value": "'
    for prefix_length in range(1, len(encoded)):
        with pytest.raises(UnicodeDecodeError):
            decode_chunks([prefix, encoded[:prefix_length]])


@pytest.mark.parametrize("invalid", [b"\xff", b"\x80", b"\xc0\xaf"])
def test_invalid_sequences_are_not_special_cased_or_replaced(invalid):
    with pytest.raises(UnicodeDecodeError):
        decode_chunks([b"prefix", invalid])


def test_public_import_contract_is_unchanged():
    assert list(inspect.signature(import_events).parameters) == ["chunks"]
